if ( ! $ps_embedded ) { get_header(); }
?>
<main class="ps-coa ps-coa-report" id="ps-coa-main">
	<nav class="ps-coa__breadcrumb" aria-label="<?php esc_attr_e( 'Breadcrumb', 'pepselect-coa-archive' ); ?>"><a href="<?php echo esc_url( $ps_context['archive_url'] ); ?>"><?php esc_html_e( 'Testing & Documentation', 'pepselect-coa-archive' ); ?></a> <span aria-hidden="true">/</span> <a href="<?php echo esc_url( $compound['url'] ); ?>"><?php echo esc_html( $compound['display_name'] ); ?></a> <span aria-hidden="true">/</span> <span aria-current="page"><?php echo esc_html( $test['batch_number'] ); ?></span></nav>
	<header class="ps-coa__header">
		<h1><?php echo esc_html( $compound['display_name'] ); ?></h1>
